  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n  url      = env(\"IDENTITY_DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"./client\"\n}\n\nmodel User {\n  id          String            @id @default(uuid())\n  phoneNumber String            @unique\n  email       String?           @unique\n  fullName    String?\n  status      String            @default(\"ACTIVE\")\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n  sessions    Session[]\n  memberships Membership[]\n  addresses   CustomerAddress[]\n\n  @@map(\"users\")\n}\n\nmodel CustomerAddress {\n  id          Int      @id @default(autoincrement())\n  userId      String\n  type        String   @default(\"Home\")\n  fullAddress String\n  landmark    String?\n  city        String   @default(\"Akola\")\n  pincode     String   @default(\"444001\")\n  latitude    Float?\n  longitude   Float?\n  isDefault   Boolean  @default(false)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  user        User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"customer_addresses\")\n}\n\nmodel Session {\n  id        String   @id @default(uuid())\n  userId    String\n  tokenHash String\n  userAgent String?\n  ipAddress String?\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"sessions\")\n}\n\nmodel Membership {\n  id        String   @id @default(uuid())\n  userId    String\n  tenantId  String // Merchant Organization ID\n  outletId  String? // Optional Outlet Scope\n  role      String // e.g. MERCHANT_OWNER, OUTLET_MANAGER, CASHIER\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, tenantId, role])\n  @@index([tenantId])\n  @@map(\"memberships\")\n}\n\nmodel AuditEvent {\n  id         String   @id @default(uuid())\n  actorId    String\n  action     String\n  targetType String\n  targetId   String\n  metadata   Json?\n  occurredAt DateTime @default(now())\n\n  @@index([actorId])\n  @@map(\"audit_events\")\n}\n\nmodel AdminUser {\n  id                  String                @id @default(uuid())\n  name                String\n  email               String                @unique\n  phone               String\n  status              String                @default(\"ACTIVE\") // ACTIVE, SUSPENDED\n  mfaEnabled          Boolean               @default(true)\n  isRootProtected     Boolean               @default(false)\n  tokenVersion        Int                   @default(1) // Immediate JWT invalidation on role/geo switch or suspension\n  failedLoginAttempts Int                   @default(0) // Brute-force dictionary protection\n  lockedUntil         DateTime?\n  lastLoginAt         DateTime?\n  lastLoginIp         String?\n  createdAt           DateTime              @default(now())\n  updatedAt           DateTime              @updatedAt\n  roleAssignments     AdminRoleAssignment[]\n  geoAssignments      AdminGeoAssignment[]\n  auditLogs           AdminAuditLog[]\n  piiAccessLogs       PiiAccessAuditLog[]\n\n  @@map(\"admin_users\")\n}\n\nmodel AdminRole {\n  id              String                @id @default(uuid())\n  code            String                @unique\n  title           String\n  subtitle        String?\n  hierarchyLevel  Int                   @default(4)\n  description     String?\n  requiresMfa     Boolean               @default(true)\n  isSystem        Boolean               @default(false)\n  createdAt       DateTime              @default(now())\n  updatedAt       DateTime              @updatedAt\n  roleAssignments AdminRoleAssignment[]\n  rolePermissions AdminRolePermission[]\n\n  @@map(\"admin_roles\")\n}\n\nmodel AdminPermission {\n  id              String                @id @default(uuid())\n  code            String                @unique\n  module          String\n  description     String?\n  rolePermissions AdminRolePermission[]\n\n  @@map(\"admin_permissions\")\n}\n\nmodel AdminRoleAssignment {\n  id         String    @id @default(uuid())\n  userId     String\n  roleId     String\n  assignedAt DateTime  @default(now())\n  user       AdminUser @relation(fields: [userId], references: [id], onDelete: Cascade)\n  role       AdminRole @relation(fields: [roleId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, roleId])\n  @@map(\"admin_role_assignments\")\n}\n\nmodel AdminRolePermission {\n  id           String          @id @default(uuid())\n  roleId       String\n  permissionId String\n  assignedAt   DateTime        @default(now())\n  role         AdminRole       @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  permission   AdminPermission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n\n  @@unique([roleId, permissionId])\n  @@map(\"admin_role_permissions\")\n}\n\nmodel AdminGeoAssignment {\n  id           String    @id @default(uuid())\n  userId       String\n  state        String\n  stateCode    String    @default(\"IN-MH\")\n  district     String\n  districtCode String    @default(\"AKL\")\n  cityId       String\n  cityCode     String    @default(\"IN-MH-AKL\") // Partition key\n  cityName     String\n  localities   Json\n  assignedAt   DateTime  @default(now())\n  user         AdminUser @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([cityId])\n  @@index([cityCode])\n  @@map(\"admin_geo_assignments\")\n}\n\nmodel AdminAuditLog {\n  id            String     @id @default(uuid())\n  operatorId    String?\n  operatorName  String\n  action        String\n  targetEntity  String\n  targetId      String\n  reasonCode    String\n  justification String\n  previousHash  String? // Cryptographic hash chain link (Blockchain-lite integrity)\n  recordHash    String? // SHA-256 HMAC of (operatorId + action + targetId + timestamp + previousHash)\n  ipAddress     String?\n  userAgent     String?\n  timestamp     DateTime   @default(now())\n  user          AdminUser? @relation(fields: [operatorId], references: [id], onDelete: SetNull)\n\n  @@index([operatorId])\n  @@index([targetEntity])\n  @@index([timestamp])\n  @@map(\"admin_audit_logs\")\n}\n\nmodel PiiAccessAuditLog {\n  id                  String     @id @default(uuid())\n  operatorId          String?\n  targetEntity        String // Customer, MerchantBank, HomeChefAddress\n  targetId            String\n  accessedFields      String[] // [\"phoneNumber\", \"residentialAddress\", \"bankAccountNumber\"]\n  purposeCode         String // ORDER_FULFILLMENT_TRIAGE, REGULATORY_KYC_VERIFICATION, DISPUTE_RESOLUTION\n  justification       String\n  consentVerification String?\n  timestamp           DateTime   @default(now())\n  user                AdminUser? @relation(fields: [operatorId], references: [id], onDelete: SetNull)\n\n  @@index([operatorId, timestamp])\n  @@index([targetEntity, targetId])\n  @@map(\"pii_access_audit_logs\")\n}\n",
